//! Public-domain melodic themes the players can quote, embedded at build time.
//! Generated by tools/extract_themes.py from the music21 corpus (see
//! assets/themes/LICENSE); the binary only parses the small text table.

use std::sync::OnceLock;

static DATA: &str = include_str!("../assets/themes/themes.txt");

#[derive(Clone, Copy, Debug)]
pub struct TNote {
    /// diatonic degree from the tonic (0 = tonic, 7 = octave); None = rest
    pub deg: Option<i32>,
    /// chromatic alteration in semitones
    pub alt: i32,
    /// duration in 1/12 quarter notes
    pub len: u32,
}

#[derive(Debug)]
#[allow(dead_code)] // provenance fields are kept for --list-themes style tooling and tests
pub struct Theme {
    pub title: &'static str,
    pub composer: &'static str,
    pub cat: &'static str,
    pub coll: &'static str,
    pub src: &'static str,
    /// "major", "minor", "dorian", "mixolydian", "phrygian", "lydian"
    pub mode: &'static str,
    pub meter: &'static str,
    /// first note's position inside its bar (1/12 quarters)
    pub pickup: u32,
    pub notes: Vec<TNote>,
    /// position within its source (the extractor writes the best-known tunes first)
    pub rank: usize,
}

#[allow(dead_code)]
impl Theme {
    /// how likely a player is to think of this one: well-known tunes come to mind first
    pub fn fame(&self) -> f32 {
        1.0 + 2.0 * (-(self.rank as f32) / 25.0).exp()
    }
    pub fn minorish(&self) -> bool {
        matches!(self.mode, "minor" | "dorian" | "phrygian")
    }
    /// scale steps of the source mode
    pub fn steps(&self) -> [i32; 7] {
        match self.mode {
            "minor" => [0, 2, 3, 5, 7, 8, 10],
            "dorian" => [0, 2, 3, 5, 7, 9, 10],
            "mixolydian" => [0, 2, 4, 5, 7, 9, 10],
            "phrygian" => [0, 1, 3, 5, 7, 8, 10],
            "lydian" => [0, 2, 4, 6, 7, 9, 11],
            _ => [0, 2, 4, 5, 7, 9, 11],
        }
    }
    /// "Garden of Daisies, The" → "The Garden of Daisies"
    pub fn name(&self) -> String {
        for art in [", The", ", A"] {
            if let Some(t) = self.title.strip_suffix(art) {
                return format!("{} {t}", &art[2..]);
            }
        }
        self.title.to_string()
    }
    /// short name: title (composer, catalogue)
    pub fn short(&self) -> String {
        let mut who = self.composer.to_string();
        if !self.cat.is_empty() {
            who.push_str(", ");
            who.push_str(self.cat);
        }
        format!("{} ({who})", self.name())
    }
    /// full citation, e.g. "Wachet auf, ruft uns die Stimme (J.S. Bach, BWV 140.7) · music21 corpus · public domain"
    pub fn citation(&self) -> String {
        format!("{} · {} · public domain", self.short(), self.coll)
    }
    /// total length in 1/12 quarters
    pub fn len(&self) -> u32 {
        self.notes.iter().map(|n| n.len).sum()
    }
}

fn parse_note(tok: &str) -> Option<TNote> {
    let (d, l) = tok.split_once(':')?;
    let len: u32 = l.parse().ok()?;
    if d == "r" {
        return Some(TNote { deg: None, alt: 0, len });
    }
    let split = d.find(|c: char| c == '#' || c == 'b' || c == 'x').unwrap_or(d.len());
    let deg: i32 = d[..split].parse().ok()?;
    let alt = match &d[split..] {
        "" => 0,
        "#" => 1,
        "b" => -1,
        "x" => 2,
        "bb" => -2,
        _ => return None,
    };
    Some(TNote { deg: Some(deg), alt, len })
}

fn parse(data: &'static str) -> Vec<Theme> {
    let mut out = Vec::new();
    for line in data.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let f: Vec<&'static str> = line.split('|').collect();
        if f.len() != 9 {
            continue;
        }
        let Some(notes) = f[8].split_whitespace().map(parse_note).collect::<Option<Vec<_>>>() else { continue };
        if notes.iter().filter(|n| n.deg.is_some()).count() < 4 {
            continue;
        }
        let rank = out.iter().filter(|t: &&Theme| t.coll == f[3]).count();
        out.push(Theme { title: f[0], composer: f[1], cat: f[2], coll: f[3], src: f[4], mode: f[5], meter: f[6], pickup: f[7].parse().unwrap_or(0), notes, rank });
    }
    out
}

pub fn all() -> &'static [Theme] {
    static T: OnceLock<Vec<Theme>> = OnceLock::new();
    T.get_or_init(|| parse(DATA))
}

#[cfg(test)]
mod tests {
    #[test]
    fn parses_all() {
        let t = super::all();
        assert!(t.len() > 300, "{} themes", t.len());
        assert!(t.iter().any(|t| t.title.starts_with("Wachet auf")));
        for th in t {
            assert!(th.len() > 0);
        }
    }
}
